from inventory.utils.numbers import twice
# scenario-imports


class Warehouse:
    def __init__(self, values):
        self.values = list(values)

    def total(self):
        return sum(self.values)


def stock_value(values):
    # scenario-body
    return twice(Warehouse(values).total())

from inventory.stock import Warehouse, stock_value
# scenario-test-imports


def test_stock_value():
    assert stock_value([1, 2]) == 6


def test_warehouse_total():
    assert Warehouse([1, 2]).total() == 3

